    val a = parts[0].toLong()
    val b = parts[1].toLong()
    val p = parts[2].toLong()
    val x = parts[3].toLong()

    val phi = p - 1
    val invA = modPow(a, phi - 1, p) // a^{-1} mod p

    // Precompute f[k] = (k * a^k) mod p for k = 1..p-1
    val f = IntArray(phi.toInt() + 1)
    var cur = a % p
    for (k in 1..phi.toInt()) {
        f[k] = ((cur * k) % p).toInt()
        cur = (cur * a) % p
    }

    // Precompute g[t] = a^{-t} mod p for t = 0..p-1
    val g = IntArray(p.toInt())
    g[0] = 1
    var curInv = 1L
    for (t in 1 until p.toInt()) {
        curInv = (curInv * invA) % p
        g[t] = curInv.toInt()
    }

    var ans = 0L
    val pInt = p.toInt()
    val phiInt = phi.toInt()

    for (t in 0 until pInt) {
        val target = (b * g[t]) % p
        var cnt = 0L
        var k = target.toInt()
        while (k <= phiInt) {
