fun main() {
    val br = BufferedReader(InputStreamReader(System.`in`))
    val parts = br.readLine().trim().split(" ")
    val a = parts[0].toLong()
    val b = parts[1].toLong()
    val p = parts[2].toLong()
    val x = parts[3].toLong()

    val phi = p - 1
    val invA = modPow(a, phi - 1, p) // a^{-1} mod p

    var ans = 0L

    // Precompute a^k for k = 0..p-2
    var cur = 1L
    val aPow = LongArray(phi.toInt())
    for (k in 0 until phi.toInt()) {
        aPow[k] = cur
        cur = (cur * a) % p
    }

    // For each residue r = n mod p, we consider n = r + t*p
    // Equation: n * a^n ≡ b (mod p)
    // Let n = r + t*p, then a^n = a^{r + t*p} = a^r * (a^p)^t
    // Using Fermat: a^p ≡ a (mod p), so a^n ≡ a^r * a^t
    // So (r + t*p) * a^{r+t} ≡ b (mod p)
    // But modulo p, r + t*p ≡ r, and a^{r+t} ≡ a^r * a^t
    // So r * a^r * a^t ≡ b (mod p)
    // Let C_r = r * a^r (mod p). We need a^t ≡ b * C_r^{-1} (mod p)
    // t ranges over all integers such that n = r + t*p in [1, x]

    for (r in 1 until p.toInt()) {
        val ar = aPow[r % phi.toInt()]
        val Cr = (r.toLong() * ar) % p
        if (Cr == 0L) continue
        val invCr = modPow(Cr, p - 2, p)
        val target = (b * invCr) % p

        // Find t0 in [0, phi-1] such that a^t0 ≡ target (mod p)
        var t0 = -1
        // brute force discrete log since phi <= 1e6
        var valPow = 1L
        for (t in 0 until phi.toInt()) {
            if (valPow == target) {
                t0 = t
                break
            }
            valPow = (valPow * a) % p
        }
        if (t0 == -1) continue

        // All t ≡ t0 (mod phi) work.
        // For each such t, n = r + t*p must be in [1, x]
        // t >= 0, n <= x => r + t*p <= x => t <= (x - r)/p
        val maxT = (x - r) / p
        if (maxT < 0) continue

        // t = t0 + k*phi, k >= 0, t <= maxT
        if (t0.toLong() > maxT) continue
        val count = (maxT - t0) / phi + 1
        ans += count
    }

    println(ans)
}

